'use strict';
// Builds dist/gfpi_bundle.js from the isomorphic gfpi/* modules (NO Node built-ins, NO companion/). `--check` verifies freshness.
const fs = require('fs');
const path = require('path');
const { sha256Hex } = require('../gfpi/canon');

const root = path.join(__dirname, '..');
const MODULES = ['canon', 'artifacts', 'decisions', 'ledger', 'questionPlan', 'redaction', 'budget', 'providerAdapter', 'specCompiler', 'executionPackage'];
const out = path.join(root, 'dist', 'gfpi_bundle.js');

function render() {
  const sources = MODULES.map((m) => fs.readFileSync(path.join(root, 'gfpi', m + '.js'), 'utf8'));
  MODULES.forEach((m, i) => { if (/require\((?!['"]\.\/)/.test(sources[i])) throw new Error(m + ' requires a non-local module'); });
  const hash = sha256Hex(sources.join('\n\u0000\n')).slice(0, 16);
  let body = '/* AUTO-GENERATED by tools/buildGfpiBundle.js — DO NOT EDIT BY HAND.\n * Modules: ' + MODULES.join(', ') + '\n * GFPI_SOURCE_HASH=' + hash + '\n */\n(function (global) {\n  "use strict";\n  var defs = {}; var cache = {};\n  function req(name) { name = name.replace(/^\\.\\//, ""); if (cache[name]) return cache[name].exports; var m = { exports: {} }; cache[name] = m; defs[name](m, m.exports, req); return m.exports; }\n';
  MODULES.forEach((m, i) => { body += '  defs[' + JSON.stringify(m) + '] = function (module, exports, require) {\n' + sources[i] + '\n  };\n'; });
  body += '  var api = {}; ' + JSON.stringify(MODULES) + '.forEach(function (n) { api[n] = req(n); });\n  api.SOURCE_HASH = ' + JSON.stringify(hash) + ';\n  global.GFPI = api;\n})(typeof window !== "undefined" ? window : globalThis);\n';
  return { body, hash };
}

const r = render();
if (process.argv.includes('--check')) {
  const cur = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : '';
  if (cur !== r.body) { console.error('STALE dist/gfpi_bundle.js — run: node tools/buildGfpiBundle.js'); process.exit(1); }
  console.log('gfpi bundle fresh (' + r.hash + ')');
} else { fs.writeFileSync(out, r.body); console.log('gfpi bundle written (' + r.hash + ')'); }
